#include "tgcloud/telegram/validator.hpp"
namespace tgcloud::telegram { static bool ok(std::string_view s){return s.find("\"ok\":true")!=std::string_view::npos||s.find("\"ok\": true")!=std::string_view::npos;} ValidationResult validate_bot(BotClient& c,std::string_view response){auto r=response.empty()?c.get_me():ApiResponse{200,std::string(response)};if(r.http_status==401)return{Validation::invalid_token,"Telegram rejected the bot token"};if(r.http_status!=200)return{Validation::inaccessible,"Telegram API unavailable"};if(!ok(r.body))return{Validation::malformed,"Bot API response was not successful"};return{Validation::valid,"Bot token accepted"};} ValidationResult validate_channel(BotClient& c,std::string id,std::string_view response){auto r=response.empty()?c.get_chat(std::move(id)):ApiResponse{200,std::string(response)};if(r.http_status==403||r.http_status==400)return{Validation::inaccessible,"Channel is inaccessible or bot lacks permission"};if(r.http_status!=200)return{Validation::inaccessible,"Telegram API unavailable"};if(!ok(r.body))return{Validation::malformed,"Channel response was not successful"};return{Validation::valid,"Channel is accessible"};} }
